
type languageType = string[];

interface os_notificationType {
  title: string;
  subtitle: string;
  body: string;
  action: string;
}

interface payloadType {
    id: string;
  name: string;
  os_notifcation: os_notificationType;
  html: string[];
  css: string[];
  js: string[];
  assets: string[];
  start_time: string;
  end_time: string;
  platforms: string[];
  time_array?: string[];
  frequency?: string;
}

interface countryType {
  location: string;
  language: languageType;
  payload: payloadType[][];
}

export interface notificationJsonType {
  "getNotification" : boolean,
  "api-global-version": string;
  "api-version": string;
  "app-version-range": string[];
  country: countryType[];
}

export type notificationReturnConfigType = {
  latestConfig: notificationJsonType;
  location: string | null;
};


export type { countryType };